sql.sessionA:
-- Session A: empty rehearsal branch only; temporary locks, no row writes.
BEGIN;
SET LOCAL idle_in_transaction_session_timeout = '120s';
SET LOCAL lock_timeout = '2s';
DO $guard$ BEGIN
IF current_setting('neon.branch_id',true) IS DISTINCT FROM 'br-autumn-mode-aikak52t'
 OR current_database() <> 'neondb' OR current_setting('server_version_num')::int / 10000 <> 17
 THEN RAISE EXCEPTION 'Wrong lock rehearsal target'; END IF;
END $guard$;
DO $empty$ BEGIN IF EXISTS (SELECT FROM public.users) THEN RAISE EXCEPTION 'Rehearsal must have no users'; END IF; END $empty$;
DO $lock$ BEGIN IF NOT pg_try_advisory_xact_lock(20260907,3006) THEN RAISE EXCEPTION 'Lock already held'; END IF; END $lock$;
LOCK TABLE public.users IN ROW EXCLUSIVE MODE;
SELECT jsonb_build_object('branch',current_setting('neon.branch_id',true),'pid',pg_backend_pid(),
 'advisory_owned',true,'users_row_exclusive_owned',
 EXISTS(SELECT FROM pg_locks WHERE pid=pg_backend_pid() AND relation='public.users'::regclass AND mode='RowExclusiveLock' AND granted)
) AS held_locks;
-- Leave this transaction open only for Session B; execute ROLLBACK explicitly afterward.

sql.sessionB:
-- Session B: actual concurrent lock rejection and FK timeout on empty rehearsal branch only.
BEGIN;
SET LOCAL statement_timeout = '10s';
SET LOCAL lock_timeout = '2s';
SET LOCAL idle_in_transaction_session_timeout = '120s';
DO $guard$ BEGIN
IF current_setting('neon.branch_id',true) IS DISTINCT FROM 'br-autumn-mode-aikak52t'
 OR current_database() <> 'neondb' OR current_setting('server_version_num')::int / 10000 <> 17
 THEN RAISE EXCEPTION 'Wrong lock rehearsal target'; END IF;
END $guard$;
SELECT jsonb_build_object('branch',current_setting('neon.branch_id',true),'pid',pg_backend_pid(),
 'migration_lock_rejected',NOT pg_try_advisory_xact_lock(20260907,3006)) AS concurrent_migration_guard;
CREATE TABLE carearound_release.rehearsal_lock_probe (owner_user_id integer);
ALTER TABLE carearound_release.rehearsal_lock_probe ADD CONSTRAINT rehearsal_users_fk
 FOREIGN KEY (owner_user_id) REFERENCES public.users(id) ON DELETE CASCADE;
-- Expected lock_timeout (55P03); the console stops. Explicit ROLLBACK must remove the probe.
ROLLBACK;

sql.retry:
-- Retry and cleanup proof: empty rehearsal branch only, no committed schema or data changes.
BEGIN;
SET LOCAL statement_timeout = '10s';
SET LOCAL lock_timeout = '2s';
DO $guard$ BEGIN
IF current_setting('neon.branch_id',true) IS DISTINCT FROM 'br-autumn-mode-aikak52t'
 OR current_database() <> 'neondb' OR current_setting('server_version_num')::int / 10000 <> 17
 THEN RAISE EXCEPTION 'Wrong lock rehearsal target'; END IF;
IF to_regclass('carearound_release.rehearsal_lock_probe') IS NOT NULL THEN RAISE EXCEPTION 'Failed DDL was not rolled back'; END IF;
IF NOT pg_try_advisory_xact_lock(20260907,3006) THEN RAISE EXCEPTION 'Prior advisory lock was not released'; END IF;
END $guard$;
CREATE TABLE carearound_release.rehearsal_lock_probe (owner_user_id integer);
ALTER TABLE carearound_release.rehearsal_lock_probe ADD CONSTRAINT rehearsal_users_fk
 FOREIGN KEY (owner_user_id) REFERENCES public.users(id) ON DELETE CASCADE;
SELECT jsonb_build_object('branch',current_setting('neon.branch_id',true),'pid',pg_backend_pid(),
 'retry_succeeded',EXISTS(SELECT FROM pg_constraint WHERE conrelid='carearound_release.rehearsal_lock_probe'::regclass AND contype='f'),
 'users_lock_modes',(SELECT jsonb_agg(mode ORDER BY mode) FROM pg_locks WHERE pid=pg_backend_pid() AND relation='public.users'::regclass AND granted)
) AS retry_result;
ROLLBACK;
SELECT jsonb_build_object('branch',current_setting('neon.branch_id',true),
 'probe_absent',to_regclass('carearound_release.rehearsal_lock_probe') IS NULL,
 'public_tables',(SELECT count(*) FROM pg_tables WHERE schemaname='public'),
 'history_rows',(SELECT count(*) FROM carearound_release.schema_changes),
 'users',(SELECT count(*) FROM public.users),
 'remaining_test_advisory_locks',(SELECT count(*) FROM pg_locks WHERE locktype='advisory' AND classid=20260907 AND objid=3006)
) AS cleanup_result;
